 if(cx*CH<G.WW){g.fillStyle='rgba(8,18,10,.26)';for(let y=-1;y<=CH;y++)for(let x=-2;x<=CH;x++){const tx=cx*CH+x,ty=cy*CH+y;if(tx<0||ty<0||tx>=G.WW||ty>=H)continue;const t=G.map[ty*W+tx];const X=x*TILE,Y=y*TILE;
  if(t===T.TREE){g.beginPath();g.ellipse(X+30,Y+12,17,9,-.5,0,7);g.fill();}else if(t===T.ROCK){g.beginPath();g.ellipse(X+24,Y+16,10,6,-.5,0,7);g.fill();}else if(t===T.DEAD){g.beginPath();g.ellipse(X+25,Y+18,9,3,-.6,0,7);g.fill();}else if(t===T.WALL||t===T.CWALL||t===T.TOWER||t===T.FWALL){g.fillRect(X+TILE,Y-6,10,TILE);}}
  for(let y=-1;y<=CH;y++)for(let x=-1;x<=CH;x++){const tx=cx*CH+x,ty=cy*CH+y;if(tx<0||ty<0||tx>=G.WW||ty>=H)continue;if(G.map[ty*W+tx]===T.TREE)drawTreeObj(g,tx,ty,x*TILE,y*TILE);}}
