function drawPlot(p){const x=p.tx*TILE,y=p.ty*TILE;if(p.st===0)return;
 if(p.st===1){const g=1-p.t/20;ctx.strokeStyle='#5fbf4a';ctx.lineWidth=2;for(let i=0;i<4;i++){const xx=x+5+i*7;ctx.beginPath();ctx.moveTo(xx,y+27);ctx.lineTo(xx+(i%2?1:-1),y+27-4-g*14);ctx.stroke();}}
 else{for(let i=0;i<4;i++){const xx=x+5+i*7,sw=Math.sin(G.time*2+i)*1.5;ctx.strokeStyle='#c9a64a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(xx,y+28);ctx.lineTo(xx+sw,y+6);ctx.stroke();ctx.fillStyle='#f0d264';ctx.beginPath();ctx.ellipse(xx+sw,y+8,3,6,0,0,7);ctx.fill();}
  ctx.fillStyle='rgba(255,230,120,'+(.2+Math.sin(G.time*4)*.15)+')';ctx.fillRect(x,y,TILE,TILE);}}
