 if(!inR&&dk<.5){ctx.fillStyle=`rgba(255,255,255,${.8*(1-dk*2)})`;for(let i=0;i<70;i++){const a=h2(i,1,77)*6.283,e=h2(i,2,77);let ra=a-yaw;while(ra>Math.PI)ra-=6.283;while(ra<-Math.PI)ra+=6.283;if(Math.abs(ra)>1)continue;const sx=VW/2+Math.tan(ra)*f,sy=hor-e*VH*.8;if(sy<0||sy>hor)continue;ctx.fillRect(sx,sy,1.5,1.5);}}
 // Boden (niedrige Auflösung)
 const FW=Math.max(60,Math.round(VW/5)),FH=Math.max(20,Math.round((VH-Math.max(0,hor))/5));if(!fpCv||fpCv.width!==FW||fpCv.height!==FH){fpCv=document.createElement('canvas');fpCv.width=FW;fpCv.height=FH;fpG=fpCv.getContext('2d');fpImg=fpG.createImageData(FW,FH);}
 const d8=fpImg.data,y0=Math.max(0,hor);for(let j=0;j<FH;j++){const sy=y0+(j+.5)*(VH-y0)/FH,dyp=sy-hor;if(dyp<=0)continue;const dist=EYE*f/dyp;const fk=Math.min(1,dist/MAXD);
  for(let i=0;i<FW;i++){const cam=((i+.5)/FW*2-1)*plane;const wx=px+(dx+rx*cam)*dist,wy=py+(dy+ry*cam)*dist;const tx=Math.floor(wx),ty=Math.floor(wy);let col;const t=G.tileAt(tx,ty);col=t===T.TREE||t===T.FLOWER||t===T.GRASS||t===T.GRASS2?hex2(GC[G.biome(tx,ty)]||'#5f9440'):(WH[t]&&!inR?fcol(T.DIRT,''):fcol(t,G.biome(tx,ty)));
   const n=.86+h2(tx,ty,5)*.2+(((wx*4|0)+(wy*4|0))&1)*.04;const o=(j*FW+i)*4;const lv=t===T.LAVA?1.2:(.35+.65*dk);for(let k=0;k<3;k++){const v=col[k]*n*lv;d8[o+k]=v*(1-fk)+fog[k]*fk;}d8[o+3]=255;}}
 fpG.putImageData(fpImg,0,0);ctx.imageSmoothingEnabled=true;ctx.drawImage(fpCv,0,y0,VW,VH-y0);
 // Wände (Strahlen)
 const NC=Math.max(80,Math.round(VW/3)),cw=VW/NC,zb=new Float32Array(NC);
 for(let i=0;i<NC;i++){const cam=((i+.5)/NC*2-1)*plane;const rdx=dx+rx*cam,rdy=dy+ry*cam;let mx=Math.floor(px),my=Math.floor(py);const ddx=Math.abs(1/(rdx||1e-9)),ddy=Math.abs(1/(rdy||1e-9));const sx=rdx<0?-1:1,sy=rdy<0?-1:1;let sdx=(rdx<0?px-mx:mx+1-px)*ddx,sdy=(rdy<0?py-my:my+1-py)*ddy;
  const hits=[];let side=0,steps=0;zb[i]=MAXD;while(steps++<MAXD*2.2){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0;}else{sdy+=ddy;my+=sy;side=1;}const pd=side?sdy-ddy:sdx-ddx;if(pd>MAXD)break;const t=G.tileAt(mx,my);let h=WH[t];if(h==null&&inR&&(mx<G.room.x0||my<G.room.y0||mx>=G.room.x0+G.room.w||my>=G.room.y0+G.room.h))h=2.5;if(h==null)continue;
   const u=side?(px+pd*rdx)-Math.floor(px+pd*rdx):(py+pd*rdy)-Math.floor(py+pd*rdy);hits.push([pd,t,h,side,u]);if(h>=1.2&&zb[i]===MAXD)zb[i]=pd;if(h>=2.2||hits.length>5)break;}
  for(let k=hits.length-1;k>=0;k--){const [d,t,h,sd,u]=hits[k];const dd=Math.max(.08,d);const top=hor+(EYE-h)/dd*f,bot=hor+EYE/dd*f;const base=WC[t]||[150,150,150];const fk=Math.min(1,dd/MAXD),sh=(sd?.78:1)*(.35+.65*dk);
   const cc=base.map((v,q)=>v*sh*(1-fk)+fog[q]*fk);ctx.fillStyle=`rgb(${cc[0]|0},${cc[1]|0},${cc[2]|0})`;ctx.fillRect(i*cw,top,cw+.6,bot-top);
   if(fk<.85){const lh=(bot-top)/h;ctx.fillStyle=`rgba(0,0,0,${.28*(1-fk)})`;if(STONE.has(t)){for(let r=1;r<h*3;r++)ctx.fillRect(i*cw,bot-r*lh/3,cw+.6,Math.max(1,lh*.03));if(((u*3+(Math.floor(u*1)%2)*.5)%1)<.07)ctx.fillRect(i*cw,top,cw+.6,bot-top);}
    else if(WOODW.has(t)){if((u*4)%1<.1)ctx.fillRect(i*cw,top,cw+.6,bot-top);}
    else if(t===T.HOUSE){ctx.fillStyle=`rgba(70,45,25,${.85*(1-fk)})`;if(u<.08||u>.92)ctx.fillRect(i*cw,top,cw+.6,bot-top);ctx.fillRect(i*cw,top+(bot-top)*.45,cw+.6,lh*.12);ctx.fillRect(i*cw,top,cw+.6,lh*.1);if(u>.35&&u<.65){ctx.fillStyle=`rgba(40,60,90,${.8*(1-fk)})`;ctx.fillRect(i*cw,top+(bot-top)*.18,cw+.6,(bot-top)*.2);}}}}}
 // Sprites
 const spr=[];const add=(x,y,fn,sc,ht)=>{const ox=x/TILE-px,oy=y/TILE-py;const d=ox*dx+oy*dy;if(d<.25||d>MAXD)return;const lat=ox*rx+oy*ry;const sx=VW/2+(lat/d)/plane*(VW/2);if(sx<-VW*.3||sx>VW*1.3)return;spr.push({d,sx,x,y,fn,sc:sc||1,ht:ht||1.5});};
 for(const m of G.mons)if(!m.dead)add(m.x,m.y,()=>drawMonster(m),1.6);for(const n of G.NPCS)if(G.npcVisible(n)&&(G.room?n.loc===G.room:!n.loc))add(n.x,n.y,()=>drawNPC(n),1.6);for(const c of (G.room?[]:G.CATS||[]))add(c.x,c.y,()=>drawCat2(c),1.6);for(const h of G.HORSES||[])if(G.horseVisible(h))add(h.x,h.y,()=>drawHorse2(h),2.4);if(G.PET&&G.PET.room===G.room)add(G.PET.x,G.PET.y,()=>drawCat2(G.PET),1.6);for(const g of G.grounds)add(g.x,g.y,()=>drawGround(g),1.2);for(const p of G.proj)add(p.x,p.y,()=>drawProj(p),1.3);for(const p of G.pproj)add(p.x,p.y,()=>drawPProj(p),1.3);
 if(!inR){const r=12;for(let ty=Math.floor(py)-r;ty<=Math.floor(py)+r;ty++)for(let tx=Math.floor(px)-r;tx<=Math.floor(px)+r;tx++){if(G.tileAt(tx,ty)!==T.TREE)continue;add((tx+.5)*TILE,(ty+.94)*TILE,()=>drawTreeObj(ctx,tx,ty,tx*TILE,ty*TILE),2.6);}}
 spr.sort((a,b)=>b.d-a.d);R._noLbl=true;
 for(const sp of spr){const s=f/(sp.d*TILE)*sp.sc,gy=hor+EYE/sp.d*f;const half=TILE*1.2*s;const c0=Math.max(0,Math.floor((sp.sx-half)/cw)),c1=Math.min(NC-1,Math.ceil((sp.sx+half)/cw));ctx.save();ctx.beginPath();let any=false;for(let i=c0;i<=c1;i++)if(zb[i]>sp.d){ctx.rect(i*cw,0,cw+.7,VH);any=true;}if(!any){ctx.restore();continue;}ctx.clip();
  const fk=Math.min(1,sp.d/MAXD);ctx.globalAlpha=1-fk*fk;ctx.setTransform(s*dpr,0,0,s*dpr,(sp.sx-sp.x*s)*dpr,(gy-sp.y*s)*dpr);try{sp.fn();}catch(e){}ctx.restore();ctx.globalAlpha=1;}
 R._noLbl=false;ctx.setTransform(dpr,0,0,dpr,0,0);
 if(!inR&&dk<.95){ctx.fillStyle=`rgba(5,8,25,${(1-dk)*.45})`;ctx.fillRect(0,0,VW,VH);}
 // Waffe in der Hand
 const w=G.held();const sw=P.swing>0?1-P.swing/.22:-1,mv=P.moving?Math.sin(G.time*7)*1.6:0;const bx=VW*.72,by=VH+10+Math.abs(mv);const K=w?G.WKIND[w.kind]:null;const look=G.playerLook();
 ctx.save();ctx.translate(bx,by);if(K&&K.thrust){ctx.translate(-VW*.06,sw>=0?-Math.sin(sw*Math.PI)*VH*.18:0);ctx.rotate(-.35);}else if(K&&K.cls==='melee'){ctx.rotate(sw>=0?-.9+sw*1.6:-.25);}else ctx.rotate(-.15);
 const sz=Math.min(VW,VH)*.42;if(w){const ic=G.icon(w).cv;ctx.save();ctx.translate(0,-sz*.55);ctx.rotate(-Math.PI/4);ctx.drawImage(ic,-sz*.5,-sz*.5,sz,sz);ctx.restore();}
 ctx.fillStyle=look.body||'#3d6fb6';ctx.fillRect(-sz*.11,-sz*.12,sz*.24,sz*.5);ctx.fillStyle=look.skin||'#f1c27d';ctx.beginPath();ctx.ellipse(0,-sz*.16,sz*.12,sz*.1,0,0,7);ctx.fill();ctx.strokeStyle='rgba(0,0,0,.35)';ctx.lineWidth=1.5;for(let k=0;k<3;k++){ctx.beginPath();ctx.moveTo(-sz*.08+k*sz*.05,-sz*.2);ctx.lineTo(-sz*.08+k*sz*.05,-sz*.12);ctx.stroke();}ctx.restore();
